import {weaponIntrinsics,itemBaseValues} from './weapon-intrinsics.js?v=23';
import {divineMerit,divineSlots} from './divine-merits.js?v=23';
import {affixQuality,nativePerfect,ROLL_GRADES} from './affix-quality.js?v=23';
export function inspectorMarkup(v){const {item:i,player:p,equipped,price,delta,upgrade,art,valueText,optName,runeValue,canExtend,catalog}=v,esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const intrinsic=weaponIntrinsics(i,p.classId);const merit=divineMerit(i),attuned=divineSlots(p).includes(i.slot);
const affixes=(i.options||[]).map(a=>{const q=affixQuality(i,a,catalog);return `<div class="rollRow" data-roll-grade="${q.key}" style="--roll-color:${q.color}"><span class="rollName">${optName(a.type)}</span><strong>+${valueText(a.type,a.value)}${q.cap?`<small> / ${valueText(a.type,q.cap)}</small>`:''}</strong><span class="rollBadge">${q.label}${q.percent!==null?' · '+q.percent.toFixed(2)+'% do teto':''}</span><i class="rollMeter"><b style="width:${Math.min(100,q.percent||0)}%"></b></i></div>`;}).join('');
return `<div class="itemInspector"><div class="inspectSummary"><div class="inspectArt rarity-${i.quality.replaceAll('+','p')}">${art}<b>${i.quality} +${i.enchant}</b></div><div class="inspectBasics"><div class="inspectState"><b>${equipped?'EQUIPADO':p.level<i.level?'REQUER NV'+i.level:'NA MOCHILA'}</b><span>${equipped?'No personagem':(delta>=0?'+':'')+delta.toLocaleString('pt-BR')+' poder ao equipar'}</span></div><div class="inspectBaseGrid">${Object.entries(itemBaseValues(i)).filter(([,n])=>n>0).map(([k,n])=>`<span>${{atk:'ATK',af:'ATK',am:'ATK',mp:'MP',hp:'HP',def:'Defesa',acc:'Precisão'}[k]||k}<b>${(n*(i.quality==='ULTRA'?2.7:1)*(1+i.enchant*({atk:.012,af:.012,am:.012,def:.012,hp:.008,acc:.006}[k]||0))).toLocaleString('pt-BR',{maximumFractionDigits:1})}</b></span>`).join('')}${intrinsic.crit?`<span>Taxa crítica fixa<b>+${(intrinsic.crit*100).toFixed(1)}%</b></span><span>Dano crítico fixo<b>+${(intrinsic.critd*100).toFixed(1)}%</b></span>`:''}</div>${p.classId==='RUP'&&i.slot==='weapon'?'<small class="twoHandNote">DUAS MÃOS · ocupa principal e secundária · orçamento duplo</small>':''}</div></div><div class="inspectActionBar"><button class="primary" id="enchantItem" ${i.enchant>=100?'disabled':''}>${i.enchant>=100?'ENCANTAMENTO MÁXIMO':'APRIMORAR +'+(i.enchant+1)}<small>${i.enchant>=100?'Limite +100 atingido':price.gold.toLocaleString('pt-BR')+' ouro · '+price.crystals+' cristais · '+Math.round(price.chance*100)+'% · +'+upgrade.toLocaleString('pt-BR')+' poder'}</small></button><button class="smallbtn cashAction" id="cashEnchantItem" ${i.enchant>=100?'disabled':''}>TENTAR COM CASH<small>Ver custo e confirmar uma tentativa</small></button></div><div class="inspectTools"><button class="smallbtn" id="equipItem">${equipped?'DESEQUIPAR':'EQUIPAR'}</button><button class="smallbtn" id="runeItem" ${i.slots<=i.runes.length?'disabled':''}>INSERIR RUNA · ${p.runes}</button>${canExtend?'<button class="smallbtn cashAction" id="cashExtendItem">3º SLOT · CASH</button>':''}<button id="backInventory" class="textlink">← Mochila</button></div>${merit?`<section class="divineCard"><div><b>✦ ${merit.name}</b><small>${i.quality==='ULTRA'?'ULTRA · valor superior':'DIVINO · valor inicial'} · ${attuned?'RESSONÂNCIA SELECIONADA':'INATIVA'}${!equipped?' · equipe para receber bônus':''}</small><p>${merit.description} Não escala com encantamento nem slots.</p></div><button class="smallbtn" id="attuneDivine">${attuned?'DESATIVAR':'RESSOAR'}</button></section>`:''}${i.quality==='ULTRA'?'<section class="divineCard"><b>ASSINATURA ULTRA</b><p>'+(['weapon','secondary'].includes(i.slot)?'Penetração e ignorar resistências, proporcionais ao orçamento da arma. Crítico fixo está na base acima e não é multiplicado pelo encantamento.':'+75 redução por impacto · +4pp resistência dano crítico · +2,5pp resistência AMP · +1,2pp tenacidade')+'</p></section>':''}<section class="inspectAffixes"><div class="inspectSectionTitle"><b>Opções adicionais · ${i.options.length}/3</b><small>${nativePerfect(i,catalog)?'3 OPÇÕES PERFEITAS':'Valor atual / teto desta peça'}</small></div>${affixes||'<p class="inspectEmpty">Peça comum: sem opções adicionais.</p>'}</section><section class="inspectSockets"><div class="inspectSectionTitle"><b>Encaixes · ${i.runes.length}/${i.slots}</b><small>Valores fixos do grau</small></div><div class="runeSlots">${Array.from({length:i.slots},(_,n)=>`<span>${i.runes[n]?'◆ '+optName(i.runes[n].type)+' +'+valueText(i.runes[n].type,runeValue(i,i.runes[n],n)):'◇ Livre'}</span>`).join('')||'<small>Sem encaixes.</small>'}</div></section><details class="inspectExtra"><summary>Qualidade, materiais e regras</summary><div class="rollLegend">${['weak','fair','good','perfect'].map((k,n)=>`<span style="color:${ROLL_GRADES[k].color}">${ROLL_GRADES[k].label} · ${['<75%','75–<90%','90–<100%','100%'][n]}</span>`).join('')}</div><p>As cores medem o sorteio em relação ao teto do atributo nesta peça, não a utilidade para a classe. Ex.: dano crítico 22% / 30% = 73,33% do teto: Fraco. Um valor perfeito só aparece no teto. Runas são fixas e não usam essa classificação.</p><p>Ouro ${p.gold.toLocaleString('pt-BR')} · cristais ${p.shards}. Garantia ${i.attempts||0}/${price.pity}. Aprimoramento aumenta somente a base; opções adicionais e runas não são multiplicadas.</p><p>Terceiro slot exige nível175+, peça175+, SS+ ou superior e dois slots naturais. Usa Extensor Astral e a tabela estendida de atributos.</p>${!equipped?'<button class="smallbtn" id="sellItem">Vender por 15 ouro</button>':''}${p.testMode?'<button class="smallbtn" id="labEnchant">TESTE: visualizar +100</button>':''}${canExtend?'<button class="smallbtn" id="extendItem">Estender · '+(p.materials?.['Extensor Astral']||0)+' extensor(es)</button>':''}${p.testMode&&canExtend?'<button class="smallbtn" id="labExtend">TESTE: abrir terceiro slot</button>':''}</details></div>`;}
